integer nrow, ncol, r, c, top, sz, ndie, nring, ncl, big
integer ex, ey, qr, qc, nr, nc, dr, dc
integer g(256,256), lab(256,256), sr(65536), sc(65536)
integer*8 d2, dmax, lhs, rhs

read(5,*) nrow, ncol
for (r = 1; r <= nrow; r = r + 1) {
  read(5,*) (g(r,c), c = 1, ncol)
}

# largest squared distance over all dies
dmax = 0
ndie = 0
for (r = 1; r <= nrow; r = r + 1) {
  for (c = 1; c <= ncol; c = c + 1) {
    if (g(r,c) != 0) {
      ndie = ndie + 1
      ex = 2*r - nrow - 1
      ey = 2*c - ncol - 1
      d2 = ex*ex + ey*ey
      if (d2 > dmax) dmax = d2
    }
  }
}

# failing dies in the ring 50%..100%: 2500*dmax <= 10000*d2
nring = 0
lhs = 2500 * dmax
for (r = 1; r <= nrow; r = r + 1) {
  for (c = 1; c <= ncol; c = c + 1) {
    if (g(r,c) == 2) {
      ex = 2*r - nrow - 1
      ey = 2*c - ncol - 1
      d2 = ex*ex + ey*ey
      rhs = 10000 * d2
      if (lhs <= rhs) nring = nring + 1
    }
  }
}

# 8-connected clusters of failing dies, iterative flood fill
for (r = 1; r <= nrow; r = r + 1) {
  for (c = 1; c <= ncol; c = c + 1) {
    lab(r,c) = 0
  }
}

ncl = 0
big = 0
for (r = 1; r <= nrow; r = r + 1) {
  for (c = 1; c <= ncol; c = c + 1) {
    if (g(r,c) == 2) {
      if (lab(r,c) == 0) {
        top = 1
        sr(top) = r
        sc(top) = c
        lab(r,c) = 1
        sz = 0
        while (top > 0) {
          qr = sr(top)
          qc = sc(top)
          top = top - 1
          sz = sz + 1
          for (dr = -1; dr <= 1; dr = dr + 1) {
            for (dc = -1; dc <= 1; dc = dc + 1) {
              nr = qr + dr
              nc = qc + dc
              if (nr >= 1) {
                if (nr <= nrow) {
                  if (nc >= 1) {
                    if (nc <= ncol) {
                      if (g(nr,nc) == 2) {
                        if (lab(nr,nc) == 0) {
                          lab(nr,nc) = 1
                          top = top + 1
                          sr(top) = nr
                          sc(top) = nc
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
        if (sz >= 5) ncl = ncl + 1
        if (sz > big) big = sz
      }
    }
  }
}

write(6,*) nring, ndie, ncl, big
end

integer nrow, ncol, r, c, j, g(256,256), vis(256,256), stk(70000)
integer sp, cur, nr, nc, dr, dc, nd, fails, cs, best, ncl, cr, cc
double precision dd, dmax2
read(5,*) nrow, ncol
for (r = 1; r <= nrow; r = r + 1)
  read(5,*) (g(r,j), j = 1, ncol)
for (r = 1; r <= nrow; r = r + 1)
  for (c = 1; c <= ncol; c = c + 1)
    vis(r,c) = 0
dmax2 = 0d0
nd = 0
for (r = 1; r <= nrow; r = r + 1)
  for (c = 1; c <= ncol; c = c + 1)
    if (g(r,c) != 0) {
      nd = nd + 1
      dd = (2d0*(r-1) - (nrow-1))**2 + (2d0*(c-1) - (ncol-1))**2
      if (dd > dmax2) dmax2 = dd
    }
fails = 0
for (r = 1; r <= nrow; r = r + 1)
  for (c = 1; c <= ncol; c = c + 1)
    if (g(r,c) == 2) {
      dd = (2d0*(r-1) - (nrow-1))**2 + (2d0*(c-1) - (ncol-1))**2
      if (2500d0*dmax2 <= 10000d0*dd) fails = fails + 1
    }
ncl = 0
best = 0
for (r = 1; r <= nrow; r = r + 1)
  for (c = 1; c <= ncol; c = c + 1)
    if (g(r,c) == 2) {
      if (vis(r,c) == 0) {
        vis(r,c) = 1
        sp = 1
        stk(1) = r*512 + c
        cs = 0
        while (sp > 0) {
          cur = stk(sp)
          sp = sp - 1
          cr = cur / 512
          cc = cur - cr*512
          cs = cs + 1
          for (dr = -1; dr <= 1; dr = dr + 1)
            for (dc = -1; dc <= 1; dc = dc + 1) {
              nr = cr + dr
              nc = cc + dc
              if (nr >= 1)
                if (nr <= nrow)
                  if (nc >= 1)
                    if (nc <= ncol)
                      if (g(nr,nc) == 2)
                        if (vis(nr,nc) == 0) {
                          vis(nr,nc) = 1
                          sp = sp + 1
                          stk(sp) = nr*512 + nc
                        }
            }
        }
        if (cs >= 5) ncl = ncl + 1
        if (cs > best) best = cs
      }
    }
write(6,*) fails, nd, ncl, best
end

