integer nrow, ncol, r, c, k, dies, fails, ringf, best, sz, top, cr, cc, nr, nc, yld, a, b
integer g(256,256), vis(256,256), sr(65536), sc(65536)
integer*8 d2, t, dmax

read(5,*) nrow, ncol
do r = 1, nrow {
  read(5,*) (g(r,c), c = 1, ncol)
}

dies = 0
fails = 0
dmax = 0
for (r = 1; r <= nrow; r = r + 1) {
  for (c = 1; c <= ncol; c = c + 1) {
    vis(r,c) = 0
    if (g(r,c) == 1 | g(r,c) == 2) {
      dies = dies + 1
      if (g(r,c) == 2) fails = fails + 1
      a = 2*r - nrow - 1
      b = 2*c - ncol - 1
      d2 = a*a + b*b
      if (d2 > dmax) dmax = d2
    }
  }
}

# ring from 0% to 100%: lo^2*D2 <= 10000*d2 <= hi^2*D2 with lo=0, hi=100
ringf = 0
for (r = 1; r <= nrow; r = r + 1) {
  for (c = 1; c <= ncol; c = c + 1) {
    if (g(r,c) == 2) {
      a = 2*r - nrow - 1
      b = 2*c - ncol - 1
      d2 = a*a + b*b
      t = 10000*d2
      if (t >= 0 & t <= 10000*dmax) ringf = ringf + 1
    }
  }
}

# largest 4-connected cluster of failing dies (iterative flood fill)
best = 0
for (r = 1; r <= nrow; r = r + 1) {
  for (c = 1; c <= ncol; c = c + 1) {
    if (g(r,c) == 2 & vis(r,c) == 0) {
      vis(r,c) = 1
      top = 1
      sr(1) = r
      sc(1) = c
      sz = 0
      while (top > 0) {
        cr = sr(top)
        cc = sc(top)
        top = top - 1
        sz = sz + 1
        do k = 1, 4 {
          nr = cr
          nc = cc
          if (k == 1) nr = cr - 1
          if (k == 2) nr = cr + 1
          if (k == 3) nc = cc - 1
          if (k == 4) nc = cc + 1
          if (nr >= 1 & nr <= nrow) {
            if (nc >= 1 & nc <= ncol) {
              if (g(nr,nc) == 2 & vis(nr,nc) == 0) {
                vis(nr,nc) = 1
                top = top + 1
                sr(top) = nr
                sc(top) = nc
              }
            }
          }
        }
      }
      if (sz > best) best = sz
    }
  }
}

if (dies > 0)
  yld = 1000*(dies - fails)/dies
else
  yld = 0

