      ai = 2*(r-1) - (nrow-1)
      bi = 2*(c-1) - (ncol-1)
      d2 = ai*ai + bi*bi
      if (d2 > dmax) dmax = d2
    }
  }
}

# count failing dies, ring fails, and edge fails
fails = 0
edgef = 0
ringf = 0
do r = 1, nrow {
  do c = 1, ncol {
    if (g(r,c) == 2) {
      fails = fails + 1
      ai = 2*(r-1) - (nrow-1)
      bi = 2*(c-1) - (ncol-1)
      d2 = ai*ai + bi*bi
      if (900*dmax <= 10000*d2 & 10000*d2 < 4900*dmax) ringf = ringf + 1
      e = 0
      if (r == 1) e = 1
      if (r == nrow) e = 1
      if (r > 1) { if (g(r-1,c) == 0) e = 1 }
      if (r < nrow) { if (g(r+1,c) == 0) e = 1 }
      if (c == 1) e = 1
      if (c == ncol) e = 1
      if (c > 1) { if (g(r,c-1) == 0) e = 1 }
      if (c < ncol) { if (g(r,c+1) == 0) e = 1 }
      if (e == 1) edgef = edgef + 1
    }
