                  if (g(nr,nc) == 2) {
                    g(nr,nc) = 1
                    sp = sp + 1
                    sr(sp) = nr
                    sc(sp) = nc
                  }
                }
              }
            }
          }
        }
      }
      if (sz >= 10) clus = clus + 1
    }
  }
}

